def flatten_list(coll):
    result = []
    if isinstance(coll, dict):
        # For dicts, flatten keys and values separately
        for k, v in coll.items():
            result.extend(flatten_list(k))
            result.extend(flatten_list(v))
    elif isinstance(coll, Iterable) and not isinstance(coll, (str, bytes)):
