        # Construct the next palindrome candidate by mirroring left half to right
        half = (length + 1) // 2
        left = s[:half]
        if length % 2 == 0:
            pal = left + left[::-1]
        else:
            pal = left + left[:-1][::-1]

        if int(pal) >= int(s):
