def min_Jumps(d, length):
    d = abs(d)
    if d == 0:
        return 0
    if length == 0:
        return -1  # impossible to move

    # If length > d and length != d, can't reach exactly (d,0) in one move or overshoot
    if length > d and length != d:
        return -1

    # If length divides d exactly
    if d % length == 0:
        return int(d // length)

