def parse_nested_parens(paren_string: str) -> List[int]:
    if not paren_string.strip():
        return []

    groups = paren_string.split()
    depths = []

    for group in groups:
        max_depth = 0
        current_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        depths.append(max_depth)

    return depths

