        return True

    n = len(arr)

    # Check if already sorted (zero shifts)
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Try all possible right shifts
    # A right shift by k means arr[-k:] + arr[:-k]
    for k in range(1, n):
