def anti_shuffle(s):
    # Split the string into words and spaces preserving the order
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        # If it's all spaces, keep as is
        if part.isspace():
            result.append(part)
        else:
            # Sort the characters of the word alphabetically
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)

